<?php
require 'db.php'; session_start(); require 'includes.php';
if (($_SESSION['user_role'] ?? '') !== 'admin') { header('Location: login.php'); exit; }
function student_redirect(): void { header('Location: admin_students.php'); exit; }
if ($_SERVER['REQUEST_METHOD']==='POST') {
  $action=$_POST['action']??'';$id=(int)($_POST['id']??0);
  if($action==='delete'){ $conn->begin_transaction();try{$q=$conn->prepare("SELECT room_id FROM room_requests WHERE user_id=? AND status IN ('Pending','Approved') FOR UPDATE");$q->bind_param('i',$id);$q->execute();$held=$q->get_result();while($row=$held->fetch_assoc()){$roomId=(int)$row['room_id'];$u=$conn->prepare("UPDATE rooms SET available_beds=LEAST(total_beds,available_beds+1),room_status=CASE WHEN room_status='Maintenance' THEN 'Maintenance' ELSE 'Available' END WHERE id=?");$u->bind_param('i',$roomId);$u->execute();}$q=$conn->prepare("DELETE FROM users WHERE id=? AND role='student'");$q->bind_param('i',$id);$q->execute();if(!$q->affected_rows)throw new Exception('Student account not found.');$conn->commit();flash('success','Student account, requests and allocated bed were handled successfully.');}catch(Throwable $e){$conn->rollback();flash('error',$e->getMessage());}student_redirect(); }
  if($action==='edit'){ $name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$branch=trim($_POST['branch']??'');$address=trim($_POST['address']??'');if(!$name){flash('error','Student name is required.');student_redirect();}$q=$conn->prepare('UPDATE users SET name=?,phone_number=?,branch=?,permanent_address=? WHERE id=? AND role=\'student\'');$q->bind_param('ssssi',$name,$phone,$branch,$address,$id);$q->execute();flash('success','Student information updated.');student_redirect(); }
}
$view=null;if(isset($_GET['view'])){$id=(int)$_GET['view'];$q=$conn->prepare("SELECT u.*,r.room_number,r.room_type,req.status request_status,req.created_at request_date FROM users u LEFT JOIN room_requests req ON req.user_id=u.id AND req.status IN ('Pending','Approved') LEFT JOIN rooms r ON r.id=req.room_id WHERE u.id=? AND u.role='student' ORDER BY req.created_at DESC LIMIT 1");$q->bind_param('i',$id);$q->execute();$view=$q->get_result()->fetch_assoc();}
$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$q=$conn->prepare("SELECT * FROM users WHERE id=? AND role='student'");$q->bind_param('i',$id);$q->execute();$edit=$q->get_result()->fetch_assoc();}
$search=trim($_GET['q']??'');$sort=$_GET['sort']??'created_at';$allowed=['name','email','branch','created_at'];if(!in_array($sort,$allowed,true))$sort='created_at';$page=max(1,(int)($_GET['page']??1));$per=10;$where=" WHERE u.role='student' ";$params=[];$types='';if($search!==''){$where.=' AND (u.name LIKE ? OR u.email LIKE ? OR u.branch LIKE ?)';$like="%$search%";$params=[$like,$like,$like];$types='sss';}$count=$conn->prepare("SELECT COUNT(*) c FROM users u $where");if($params)$count->bind_param($types,...$params);$count->execute();$total=(int)$count->get_result()->fetch_assoc()['c'];$pages=max(1,ceil($total/$per));$page=min($page,$pages);$offset=($page-1)*$per;$sql="SELECT u.*,r.room_number,req.status request_status FROM users u LEFT JOIN room_requests req ON req.user_id=u.id AND req.status IN ('Pending','Approved') LEFT JOIN rooms r ON r.id=req.room_id $where ORDER BY u.$sort ASC LIMIT ? OFFSET ?";$stmt=$conn->prepare($sql);$p=$params;$p[]=$per;$p[]=$offset;$stmt->bind_param($types.'ii',...$p);$stmt->execute();$students=$stmt->get_result();$flash=consume_flash();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Management · StaySpace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/app.css"><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script></head><body><div class="app"><aside class="sidebar"><div class="brand"><i class="fa-solid fa-building-shield"></i><span>StaySpace</span></div><div class="nav-label">ADMIN CONTROL</div><nav class="nav"><a href="admin_dashboard.php"><i class="fa-solid fa-chart-pie"></i><span>Dashboard</span></a><a href="admin_rooms.php"><i class="fa-solid fa-bed"></i><span>Room management</span></a><a class="active" href="admin_students.php"><i class="fa-solid fa-users"></i><span>Student management</span></a><a class="logout" href="logout.php"><i class="fa-solid fa-arrow-right-from-bracket"></i><span>Sign out</span></a></nav></aside><main class="content"><header class="topbar"><div><h1>Student management</h1><p class="eyebrow">Manage accounts, profiles and room allocations.</p></div><a class="btn btn-light" href="admin_dashboard.php">Dashboard</a></header>
<?php if($view):?><section class="card"><div class="card-heading"><h2>Student profile</h2><a class="btn btn-light" href="admin_students.php">Close</a></div><div class="form-grid"><p><strong>Name</strong><br><?=e($view['name'])?></p><p><strong>Email</strong><br><?=e($view['email'])?></p><p><strong>Phone</strong><br><?=e($view['phone_number']?:'Not provided')?></p><p><strong>Branch</strong><br><?=e($view['branch']?:'Not provided')?></p><p><strong>Allocated room</strong><br><?=e($view['room_number']?:'None')?> <?=e($view['room_type']?:'')?></p><p><strong>Request status</strong><br><?=e($view['request_status']?:'No active request')?></p><p style="grid-column:1/-1"><strong>Address</strong><br><?=e($view['permanent_address']?:'Not provided')?></p></div></section><?php endif;?>
<?php if($edit):?><section class="card"><div class="card-heading"><h2>Edit student</h2><a class="btn btn-light" href="admin_students.php">Cancel</a></div><form method="post"><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=$edit['id']?>"><div class="form-grid"><div class="form-group"><label>Full name *</label><input required name="name" value="<?=e($edit['name'])?>"></div><div class="form-group"><label>Email</label><input disabled value="<?=e($edit['email'])?>"></div><div class="form-group"><label>Phone</label><input name="phone" value="<?=e($edit['phone_number'])?>"></div><div class="form-group"><label>Branch</label><input name="branch" value="<?=e($edit['branch'])?>"></div><div class="form-group" style="grid-column:1/-1"><label>Address</label><textarea name="address" rows="3"><?=e($edit['permanent_address'])?></textarea></div></div><button class="btn btn-primary" style="margin-top:18px">Save changes</button></form></section><?php endif;?>
<section class="card"><div class="card-heading"><h2>Registered students</h2><span class="muted"><?=$total?> students</span></div><form class="toolbar" method="get"><input class="field" name="q" value="<?=e($search)?>" placeholder="Search name, email or branch"><select name="sort"><?php foreach($allowed as $field):?><option value="<?=$field?>" <?=$sort===$field?'selected':''?>>Sort: <?=ucwords(str_replace('_',' ',$field))?></option><?php endforeach;?></select><button class="btn btn-primary">Search</button></form><div class="table-wrap"><table><thead><tr><th>Student</th><th>Contact</th><th>Branch</th><th>Allocated room</th><th>Request status</th><th>Actions</th></tr></thead><tbody><?php if(!$students->num_rows):?><tr><td colspan="6" class="empty">No students match your search.</td></tr><?php else:while($s=$students->fetch_assoc()):?><tr><td><strong><?=e($s['name'])?></strong><br><small class="muted">Joined <?=date('d M Y',strtotime($s['created_at']))?></small></td><td><?=e($s['email'])?><br><small class="muted"><?=e($s['phone_number']?:'No phone')?></small></td><td><?=e($s['branch']?:'—')?></td><td><?=e($s['room_number']?:'Not allocated')?></td><td><?php if($s['request_status']):?><span class="badge <?=status_class($s['request_status'])?>"><?=e($s['request_status'])?></span><?php else:?><span class="muted">—</span><?php endif;?></td><td><a class="btn btn-light" href="admin_students.php?view=<?=$s['id']?>">View</a> <a class="btn btn-light" href="admin_students.php?edit=<?=$s['id']?>">Edit</a> <form method="post" action="admin_students.php" style="display:inline"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$s['id']?>"><button type="submit" class="btn btn-danger" data-confirm="Delete <?=e($s['name'])?>? Their requests will be removed and any reserved bed released.">Delete</button></form></td></tr><?php endwhile;endif;?></tbody></table></div><?php if($pages>1):?><div class="pagination"><?php for($i=1;$i<=$pages;$i++):?><a class="btn <?=$i===$page?'btn-primary':'btn-light'?>" href="?<?=http_build_query(['q'=>$search,'sort'=>$sort,'page'=>$i])?>"><?=$i?></a><?php endfor;?></div><?php endif;?></section></main></div><?php if($flash):?><div id="flash" data-type="<?=e($flash['type'])?>" data-message="<?=e($flash['text'])?>"></div><?php endif;?><script src="assets/js/app.js?v=20260726-delete-fix"></script><script>const f=document.getElementById('flash');if(f)Swal.fire({toast:true,position:'top-end',showConfirmButton:false,timer:3500,icon:f.dataset.type==='success'?'success':'error',title:f.dataset.message});</script></body></html>
